function Check-S26([bool]$OK,[string]$Name){if(-not $OK){throw ('Prova falhou: '+$Name)}}
function Record-S26([string]$Name){
 $s26Result.Provas += [ordered]@{Nome=$Name;Passou=$true;Utc=[datetime]::UtcNow.ToString('o')}
 Write-Host ('OK '+$Name)
}
function Save-S26{
