function Request-S26([string]$Origin,[string]$Case,[Nullable[int]]$Expected,[hashtable]$Headers=@{}){
 if($Origin -cnotin @($s26Front,$s26Api)){throw 'Destino fora do escopo'}
 $request=[Net.Http.HttpRequestMessage]::new([Net.Http.HttpMethod]::Get,$Origin+'/api/painel/leads')
 $response=$null;$body=$null;$clock=[Diagnostics.Stopwatch]::StartNew()
 $s26Result.Requisicoes++
 $item=[ordered]@{Numero=$s26Result.Requisicoes;Fase=$Fase;Caso=$Case;Servico=$(if($Origin -ceq $s26Api){'API'}else{'Front'});InicioUtc=[datetime]::UtcNow.ToString('o');Status=$null;Esperado=$Expected;Informativo=($null -eq $Expected);Conforme=$null;DuracaoMs=$null;FalhaTransporte=$false}
 $s26Result.Chamadas += $item
 try{
  [void]$request.Headers.TryAddWithoutValidation('X-Serverless-Authorization','Bearer '+$s26Token)
  foreach($key in $Headers.Keys){[void]$request.Headers.TryAddWithoutValidation($key,[string[]]@($Headers[$key]))}
  $response=$s26Client.SendAsync($request).GetAwaiter().GetResult()
  $item.Status=[int]$response.StatusCode
  $body=$response.Content.ReadAsStringAsync().GetAwaiter().GetResult()
  Check-S26 ([Text.Encoding]::UTF8.GetByteCount($body) -le 8192) ($Case+' resposta limitada')
  $item.Conforme=if($null -eq $Expected){$null}else{$item.Status -eq $Expected}
  $item.DuracaoMs=[math]::Round($clock.Elapsed.TotalMilliseconds,1)
  Save-S26
  Write-Host ('HTTP '+$item.Numero+' '+$Case+' '+$item.Status)
  if($null -ne $Expected){Check-S26 ($item.Status -eq $Expected) ($Case+' esperado '+$Expected+' observado '+$item.Status)}
 }catch{
  if($null -eq $item.Status){$item.FalhaTransporte=$true}
  $item.DuracaoMs=[math]::Round($clock.Elapsed.TotalMilliseconds,1);Save-S26
  throw
 }finally{$body=$null;if($response){$response.Dispose()};$request.Dispose()}
}
function Bucket-S26([string]$Origin,[string]$Name){
